/*!
 * @file      fft_tables.h
 * @brief     Twiddle factors, bit-reversal tables and bin gains for E03.
 *
 *            N = 32 points (5 stages) at fs = 48000 Hz, 1500 Hz per bin. Odd
 *            channels keep bins up to 3000 Hz.
 *
 *            Generated by `uv run coursework/E03-fft/design.py`;
 *            edit the design there, not this file.
 */

#ifndef __FFT_TABLES_H__
#define __FFT_TABLES_H__

#include <stdint.h>

/*
 * Real part of the twiddle factor W_N^k = exp(-j 2 pi k / N),
 * k = 0 .. N/2 - 1. A transform of N/2 points takes every
 * other entry.
 */
#define FFT_SAMPLE_RATE (48000u)
#define FFT_N (32u)
#define FFT_LOG2N (5u)
extern const float FftCos[FFT_N / 2u];

/*
 * sin(2 pi k / N), k = 0 .. N/2 - 1: W_N^k = FftCos[k] - j FftSin[k].
 */
extern const float FftSin[FFT_N / 2u];

/*
 * n with its FFT_LOG2N bits reversed: where input n goes before
 * the in-place butterflies of an N-point transform.
 */
extern const uint16_t FftBitRev[FFT_N];

/*
 * The same for N/2 points, which the real-input transform uses.
 */
extern const uint16_t FftBitRevHalf[FFT_N / 2u];

/*
 * Gain per bin k = 0 .. N/2 applied on odd channels: 1 up to
 * FFT_KEEP_HZ, 0 above.
 */
#define FFT_KEEP_HZ (3000u)
extern const float FftBinGain[FFT_N / 2u + 1u];

#endif /* __FFT_TABLES_H__ */
